      "prompt": "(7) 男の人と女の人が話しています。男の人はどうして遅くなりましたか。\n男：ああ、ごめん、ごめん。待った？\n女：待ったわよ。30分も。\n男：ごめんねえ。バスがなかなか来なくて。\n女：あなた、バス、乗らないでしょう。\n男：ああ、いつも駅まで自転車だからね。ああ、そうそう、自転車は壊れちゃって、もうたいへん。\n女：これもうそなんでしょう。\n男：ごめん、うそ。あのう、朝、時計が鳴らなくて、起きられなかったんだ。\n女：時計が鳴ったのに起きなかったんでしょう。\n男：ごめんなさい、そうなんだ。\n男の人はどうして遅くなりましたか。\n\n男の人はどうして遅くなりましたか。",
