      "prompt": "(11) 女の人は運動をしたいと思っています。女の人が入るクラスはいくらですか。\n男：いらっしゃいませ。はじめての方ですか。\n女：はい。あのう、1ヶ月いくらですか。\n男：ええと、走るクラスは3千円です。いろいろな運動ができるクラスは6千円になっております。\n女：ええと、泳ぐのは？\n男：このクラスは8千円になります。\n女：高いですね。\n男：はあ、冬も水を温かくしていますから。そのほかに全部の運動ができて、1万円というクラスもあります。\n女：うん、泳ぐのが好きなんだけど、ほかの運動はどうも。\n男：じゃあ、やっぱりこちらのクラスになさいますか。\n女：ええ。\n女の人が入るクラスはいくらですか。\n\n女の人が入るクラスはいくらですか。",
