    "script": "男の人と女の人が話しています。仕事が終わってからすぐ何をしますか。\n男：今日は６時ごろには仕事が終わりますね。レストランで食事でもどうですか。\n女：あ、いいですね、でも…。\n男：あ、忙しいんですか。\n女：あした友だちの誕生日のパーティーなのでプレゼントを買いに行かなければならないんです。\n男：じゃあ、食事のあと、いっしょに買い物に行きましょう。\n女：デパートは７時にしまるので、食事の前のほうが…\n男：分かりました。そうしましょう。\n仕事が終わってからすぐ何をしますか。",
