    "script": "男の人と女の人が話しています。二人はどこで会いますか。\n女：じゃ、あした６時ごろでいい？\n男：うん、いつものきっさてんだね。\n女：あ、あしたあまり時間がないから映画館の前で会いましょうよ。\n男：場所がよく分からないんだ、その映画館。\n女：じゃ、駅の前にする？\n男：さむいよ。駅の中にしない？\n女：でも人が多いでしょ。\n男：分かった分かった。じゃ、寒くてもいいよ。\n二人はどこで会いますか。",
