    "script": "男の人と女の人が話しています。女の人はあしたどうしますか。\n女：すみません、あしたの午前中お休みをいただきたいんですが。\n男：どうしたの？だいぶ具合（ぐあい）が悪そうだね。\n女：はい。で、あした医者（いしゃ）に行ってこようと思いまして。午後には出てきますから。\n男：いや、休んだほうがいいよ。疲れもあるだろうし。\n女：はい、でもあしたの午後には会議（かいぎ）もありますし…\n男：山本君がいるからいいだろう。そうしなさい。\n女：はい、もうしわけありません。\n女の人はあしたどうしますか。",
