    "script": "男の人と女の人が話しています。女の人はどんな本がほしいですか。\n女：ねぇ、何か本貸してよ。旅行の時読むから。\n男：どんなのがいいの？\n女：電車の中で読むのよ。\n男：じゃあ、これはどう？ちょっと難しいけど。\n女：そんなのじゃなくて、軽い本ない？\n男：じゃ、これは？小さいから重くないよ。\n女：そういう意味じゃないわよ。かんたんに読めるおもしろい本よ。\n男：ああそういう意味…ぼくの本はみんな難しいからなぁ。\n女：もういいわよ。自分で買ってくる。\n女の人はどんな本がほしいですか。",
