    "meaning": {
      "prompt": "2 番 男の人と女の人が会社の中で電話で話しています。女の人はこの後、すぐ何をしなければなりませんか。 男の人：もしもし、山田だけど、 女の人：あっ、課長。 男の人：僕の机のうえに、青いノートある？女の人：青いノートですか、えっ、ありませんが、 男の人：やっぱり、コピー室に置いたままだ。悪いけど、コピー室に行って、ノートがあるかどうか、見ていってくれる？女の人：はい、 男の人：で、あったら、すぐ会議室にもってきてください。 女の人：はい、わかりました。 男の人：もしなかったら、会議室に電話してくれる？急いでね。\n\n女の人はこの後、すぐ何をしなければなりませんか。",
      "options": [
        "コピー室に行って、ノートをさがします。",
        "コピー室にノートを持っていきます。",
        "会議室でノートをさがします。",
        "会議室に電話をします。"
      ],
      "answerIndex": 0
    },
    "optionExplanations": [
      "課長がまず頼んだのは「コピー室に行って、ノートがあるかどうか見てきて」ということなので、これが直後にすべき行動として正解。",
      "ノートを会議室に持っていくのは、コピー室で見つかった場合の次のステップであり、直後の行動ではないため、誤り。",
      "ノートはコピー室にあるはずなので、会議室で探すのは誤り。",
      "会議室に電話するのは、コピー室にノートがなかった場合の対応であり、直後の行動ではないため、誤り。"
    ],
    "script": "2 番 男の人と女の人が会社の中で電話で話しています。女の人はこの後、すぐ何をしなければなりませんか。 男の人：もしもし、山田だけど、 女の人：あっ、課長。 男の人：僕の机のうえに、青いノートある？女の人：青いノートですか、えっ、ありませんが、 男の人：やっぱり、コピー室に置いたままだ。悪いけど、コピー室に行って、ノートがあるかどうか、見ていってくれる？女の人：はい、 男の人：で、あったら、すぐ会議室にもってきてください。 女の人：はい、わかりました。 男の人：もしなかったら、会議室に電話してくれる？急いでね。",
