      "prompt": "3 番 男の人と女の人が話しています。正しいのはどれですか。 男の人：ヒロシさんがけがで入院しているそうですね。 女の人：いいえ、ヒロシさんじゃなくて、奥さんですよ。男の人：あっ、そうですか、足の怪我らしいですね。 女の人：いいえ、手ですよ。 男の人：あっ、そうですか。よく知っていますね。 女の人：ええ、だって、昨日、お見舞いに行きましたから。\n\n正しいのはどれですか。",
