    "meaning": {
      "prompt": "7 番 女の人が話しています。雨が降ったらどうしますか。女の人：それでは、今から、自由に過ごしてください。帰りですが、3時半に公園の入り口に集まってください。3時半ですよ。でも、もし雨が降ったら、30分早く集まることにします。それから、公園の入り口じゃなくて、あの美術館の前に集まってください。いいですね。\n\n雨が降ったらどうしますか。",
      "options": [
        "3 時半に公園の入り口に集まります。",
        "3時半に美術館の前に集まります。",
        "3時に公園の入り口に集まります。",
        "3時に美術館の前に集まります。"
      ],
      "answerIndex": 3
    },
    "notes": [
      {
        "surface": "美術館",
        "word": "美術館",
        "reading": "びじゅつかん",
        "meaning": "美術館",
        "type": "vocab"
      }
    ],
    "optionExplanations": [
      "3時半は雨が降らなかった場合の集合時間であり、集合場所も公園の入り口のままなので、誤り。",
      "集合時間が3時半のままなので、誤り（雨天時は30分早い3時が正しい）。",
      "時間は正しいが、場所が公園の入り口のままで誤り（雨天時は美術館の前が正しい）。",
      "雨が降ったら30分早い3時に、場所も公園の入り口ではなく美術館の前に変更されるので、これが正解。"
    ],
    "script": "7 番 女の人が話しています。雨が降ったらどうしますか。女の人：それでは、今から、自由に過ごしてください。帰りですが、3時半に公園の入り口に集まってください。3時半ですよ。でも、もし雨が降ったら、30分早く集まることにします。それから、公園の入り口じゃなくて、あの美術館の前に集まってください。いいですね。",
