    "meaning": {
      "prompt": "女の人と男の人が話しています。パッティにくる人は何人になりましたか？\n女：日曜日のパッティは何人にくるんですか？\n男：えっと、全部で六人です。\n女：あ、そうそう、山田さん日曜都合悪くなったそうですよ\n男：では山田さんはこられないですね\n女：それで、高橋さんは娘二人を連れてくるそうです\n男：そうですか？わかりました。\n\nパーティにくる人は何人になりましたか？",
      "options": [
        "5人",
        "6人",
        "7人",
        "8人"
      ],
      "answerIndex": 2
    },
    "script": "女の人と男の人が話しています。パッティにくる人は何人になりましたか？\n女：日曜日のパッティは何人にくるんですか？\n男：えっと、全部で六人です。\n女：あ、そうそう、山田さん日曜都合悪くなったそうですよ\n男：では山田さんはこられないですね\n女：それで、高橋さんは娘二人を連れてくるそうです\n男：そうですか？わかりました。",
    "optionExplanations": [
      "「5人」未考慮高橋帶兩個女兒同行，人數計算不完整。",
      "原本6人，山田不能來（−1人=5人），高橋帶兩個女兒來（+2人=7人），正解。",
      "「7人」計算正確但此為選項3。",
      "「8人」多算了1人，不符合正確加減。"
    ]
