    "script": "男の人と女の人がデパートで話しています。二人はこの後どこで会いますか。\n男：次は、何買うの。\n女：今度の旅行用のかばん。\n男：じゃ、５階だね。ここは２階だから、エレベーターで行く？\n女：でも、その前に、４階で、ハンカチを買いたい。\n男：分かった。じゃ、僕も３階をちょっと見に行くよ。５階のエスカレーターの前で会おう。\n女：エスカレーターは、確か、三つぐらいあるから、分かりにくいわ。あなた先に行って、いいかばん探してて、後から行くから。\n男：わかった。",
