    "script": "男の人と女の人が話しています。二人はどこで宿題をしますか。\n男：ねえ、今日の英語の宿題、よかったら、一緒にやらない。\n女：いいよ。多いし、難しそうだから。\n男：どこでする。教室？図書館のほうがいいよね。\n女：静かだし、辞書もあるからね。でも、きっと、席が開いてないよ。六時には閉まっちゃうし。よかったら、家に来る。\n男：うん。",
