    "script": "男の人と女の人が話しています。女の人は山田部長について何と言っていますか。\n男性：鈴木さんは、桜デパートの山田部長をご存知ですか。\n女性：あ、お名前は伺っていますが、お会いしたことは。\n男性：そうですか。じゃ、ちょうどよかった。来月の会議にいらっしゃいますから、ご紹介しますよ。\n女性：ありがとうございます。よろしくお願いいたします。",
