    "script": "女の人と男の人が話しています。\nＦ：あのう、お願いって何でしょうか。\nＭ：あのう、田中さんは歌やピアノを教えていらっしゃるってきいたんですが。実は来月、知り合いの結婚式があって、私がピアノを演奏して、友達が歌を歌うことになったんです。でも、私、そんなにできるわけじゃなくて、困っているんですが。あのう、お時間のあるときに教えていただけないでしょうか。\n男の人は女の人にどのようなことをお願いしていますか。",
