    "script": "アナウンサーがスーパーからリポートしています。\nＦ：こちら、スーパーの野菜売り場です。ごらんください。珍しい野菜が並んでいますね。この黄色いのなんだと思いますか。形はきゅうりですが、ちょっといただきます。う〜ん、きゅうりの味です。おいしいです。実は、技術がすすんで、簡単に野菜の色を変えられるようになったそうです。おもしろいですね。ところが、このような野菜はあまり売れていません。値段は普通の野菜と変わらないのですが。やはりおいしそうに見えないのでしょうか。それが原因かもしれません。\nアナウンサーは何についてリポートしていますか。",
